function mountMarkdown(){routePage('Markdown Studio','A clean, local-first Markdown notebook. HTML input is always escaped for safe preview.',`<div class="row" style="margin-bottom:15px"><button class="btn primary" id="md-save">Download .md</button><button class="btn" id="md-upload-btn">Import .md</button><button class="btn danger" id="md-clear">Clear</button><span class="hint" id="md-count"></span><input id="md-upload" type="file" accept=".md,.markdown,.txt" hidden></div><div class="layout-2"><section class="panel"><h2>Editor</h2><textarea class="textarea mono" id="md-input" style="min-height:440px" spellcheck="false"></textarea></section><section class="panel"><h2>Live preview</h2><article class="markdown-preview" id="md-preview"></article></section></div><p class="hint">Supports headings, bold, italic, links, lists, code blocks, blockquotes and paragraphs. This is not a full CommonMark parser.</p>`);
let txt=starter;try{txt=localStorage.getItem('mlab:markdown')??starter}catch{}$('#md-input').value=txt;function draw(){let s=$('#md-input').value;try{localStorage.setItem('mlab:markdown',s)}catch{}$('#md-count').textContent=s.trim().split(/\s+/).filter(Boolean).length+' words';let lines=s.replace(/\r/g,'').split('\n'),out='',list=false,code=false;for(let l of lines){if(l.startsWith('```')){if(list){out+='</ul>';list=false}out+=code?'</code></pre>':'<pre><code>';code=!code;continue}if(code){out+=h(l)+'\n';continue}let m=l.match(/^\s*[-*+]\s+(.*)$/);if(m){if(!list){out+='<ul>';list=true}out+='<li>'+inline(m[1])+'</li>';continue}if(list){out+='</ul>';list=false}if(!l.trim()){out+='<p></p>';continue}m=l.match(/^(#{1,6})\s+(.*)$/);if(m){let n=m[1].length;out+=`<h${n}>${inline(m[2])}</h${n}>`}else if(l.startsWith('> '))out+='<blockquote>'+inline(l.slice(2))+'</blockquote>';else out+='<p>'+inline(l)+'</p>'}if(list)out+='</ul>';if(code)out+='</code></pre>';$('#md-preview').innerHTML=out}$('#md-input').addEventListener('input',draw);$('#md-save').onclick=()=>download('notes.md',$('#md-input').value);$('#md-upload-btn').onclick=()=>$('#md-upload').click();$('#md-upload').onchange=async()=>{let f=$('#md-upload').files[0];if(f){if(f.size>2e6)return toast('File too large (max 2MB)');$('#md-input').value=await f.text();draw()}};$('#md-clear').onclick=()=>{if(confirm('Clear the entire notebook?')){$('#md-input').value='';draw()}};draw()}

