function mountDraw(){routePage('Mini Whiteboard','Sketch ideas, diagrams and notes. Export locally as PNG.',`<div class="panel stack"><div class="row"><label class="hint">Ink <input type="color" id="draw-color" value="#19273c"></label><label class="hint">Size <input type="range" id="draw-size" min="1" max="35" value="4"></label><button class="btn" id="draw-eraser">Eraser</button><button class="btn" id="draw-undo">Undo</button><button class="btn" id="draw-clear">Clear</button><button class="btn primary" id="draw-export">Save PNG</button></div><canvas id="draw-canvas" class="canvas" width="1000" height="610" aria-label="Drawing canvas"></canvas><p class="hint">Touch, mouse and pen supported. Your drawing stays on this page until you download it.</p></div>`);let c=$('#draw-canvas'),ctx=c.getContext('2d'),drawing=false,last=null,erase=false,history=[];function white(){ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height)}white();function snap(){if(history.length>=24)history.shift();history.push(ctx.getImageData(0,0,c.width,c.height))}function pos(e){let r=c.getBoundingClientRect();return{x:(e.clientX-r.left)*c.width/r.width,y:(e.clientY-r.top)*c.height/r.height}}c.onpointerdown=e=>{if(e.button!==0)return;drawing=true;last=pos(e);snap();c.setPointerCapture(e.pointerId);ctx.beginPath();ctx.arc(last.x,last.y,+$('#draw-size').value/2,0,Math.PI*2);ctx.fillStyle=erase?'#ffffff':$('#draw-color').value;ctx.fill()};c.onpointermove=e=>{if(!drawing)return;let next=pos(e);ctx.strokeStyle=erase?'#ffffff':$('#draw-color').value;ctx.lineWidth=+$('#draw-size').value;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(last.x,last.y);ctx.lineTo(next.x,next.y);ctx.stroke();last=next};c.onpointerup=c.onpointercancel=()=>drawing=false;$('#draw-eraser').onclick=()=>{erase=!erase;$('#draw-eraser').classList.toggle('active',erase)};$('#draw-undo').onclick=()=>{let prev=history.pop();if(prev)ctx.putImageData(prev,0,0);else toast('Nothing to undo')};$('#draw-clear').onclick=()=>{if(confirm('Clear the drawing?')){snap();white()}};$('#draw-export').onclick=()=>c.toBlob(b=>b?download('whiteboard.png',b):toast('Unable to export'),'image/png')}

